import zlib,struct
def load(p):
    d=open(p,'rb').read();i=8;w=h=0;idat=b'';
    while i<len(d):
        l,=struct.unpack('>I',d[i:i+4]);t=d[i+4:i+8];c=d[i+8:i+8+l];i+=12+l
        if t==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',c[:10])
        if t==b'IDAT': idat+=c
    raw=zlib.decompress(idat);bpp={6:4,2:3,3:1,4:2,0:1}[ct];stride=w*bpp;rows=[];prev=bytearray(stride);p=0
    for y in range(h):
        f=raw[p];line=bytearray(raw[p+1:p+1+stride]);p+=1+stride
        for x in range(stride):
            a=line[x-bpp] if x>=bpp else 0;b=prev[x];c=prev[x-bpp] if x>=bpp else 0
            if f==1:line[x]=(line[x]+a)&255
            elif f==2:line[x]=(line[x]+b)&255
            elif f==3:line[x]=(line[x]+(a+b)//2)&255
            elif f==4:
                pp=a+b-c;pa,pb,pc=abs(pp-a),abs(pp-b),abs(pp-c)
                line[x]=(line[x]+(a if pa<=pb and pa<=pc else b if pb<=pc else c))&255
        rows.append(line);prev=line
    return w,h,bpp,ct,rows
for n in ['closed','pressure_unlit']:
    w,h,bpp,ct,rows=load('Resources/Textures/Structures/Doors/Misc/edge_door_hazard.rsi/%s.png'%n)
    print(n,ct)
    for r in rows: print(''.join('#' if (r[x*bpp+3] if bpp==4 else 255)>0 else '.' for x in range(w)))
